        int n = s.length();

        if (n > 3)
            return false;

        for (int i = 0; i < n; i++)
            if (!(s.charAt(i) >= '0' && s.charAt(i) <= '9'))
                return false;

        if (s.indexOf('0') == 0 && n > 1)
            return false;

        try {
            int x = Integer.parseInt(s);

            // The string is valid if the number 
            // generated is between 0 to 255
            return (x >= 0 && x <= 255);
        }
        catch (NumberFormatException e) {
            return false;
        }
    }

    static int isValid(String ipStr){
        // If the empty string then return false
        if (ipStr == null)
            return 0;

        int dots = 0;
        int len = ipStr.length();
        int count = 0;

        for (int i = 0; i < len; i++)
            if (ipStr.charAt(i) == '.')
                count++;
        if (count != 3)
            return 0;

        // Using StringTokenizer to 
        // split the IP string
        StringTokenizer st
            = new StringTokenizer(ipStr, ".");

        while (st.hasMoreTokens()) {
            String part = st.nextToken();

            // After parsing string, 
            // it must be valid
            if (isValidPart(part)) {
                // Parse remaining string
                if (st.hasMoreTokens())
                    dots++;
            }
            else
                return 0;
        }
        if (dots != 3)
            return 0;

        return 1;
    }

